-- ----------------------------
-- Table structure for oa_bill_correction_state
-- ----------------------------
DROP TABLE IF EXISTS `oa_bill_correction_state`;
CREATE TABLE `oa_bill_correction_state`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据类型（流程定义Key，如 oa_contract_bill）',
  `bill_id` bigint(20) NOT NULL COMMENT '单据ID',
  `freeze_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '冻结状态（0正常 1已冻结）',
  `correction_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '纠错状态（0无 1纠错中 2已完成 3理事会推翻）',
  `last_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纠错前流程实例ID',
  `active_correction_bill_id` bigint(20) NULL DEFAULT NULL COMMENT '进行中的纠错单ID',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_type_id`(`bill_type` ASC, `bill_id` ASC) USING BTREE,
  INDEX `idx_freeze_status`(`freeze_status` ASC) USING BTREE,
  INDEX `idx_correction_status`(`correction_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '业务单据纠错冻结状态' ROW_FORMAT = Dynamic;

