-- ----------------------------
-- Table structure for oa_contract_payment_plan
-- ----------------------------
DROP TABLE IF EXISTS `oa_contract_payment_plan`;
CREATE TABLE `oa_contract_payment_plan`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_id` bigint(20) NOT NULL COMMENT '合同审批单ID',
  `period` int(11) NULL DEFAULT NULL COMMENT '期次',
  `plan_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '计划金额',
  `plan_date` date NULL DEFAULT NULL COMMENT '计划日期',
  `actual_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '实际金额',
  `actual_date` date NULL DEFAULT NULL COMMENT '实际日期',
  `status` int(11) NULL DEFAULT 0 COMMENT '状态（0待收付 1已收付 2已逾期）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_bill_id`(`bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收付款计划' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_contract_payment_plan
-- ----------------------------

-- ----------------------------
-- Table structure for oa_correction_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_correction_bill`;
CREATE TABLE `oa_correction_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '流程状态（0草稿 1审批中 2已通过 3已拒绝 4已取消）',
  `source_bill_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原单据类型',
  `source_bill_id` bigint(20) NOT NULL COMMENT '原单据ID',
  `source_bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原单据编号',
  `source_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原流程实例ID',
  `source_bill_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原单据标题',
  `correction_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '撤销/纠错理由',
  `correction_type` tinyint(4) NULL DEFAULT 1 COMMENT '纠错类型（1异议纠错 2理事会决议）',
  `revoke_time` datetime NULL DEFAULT NULL COMMENT '撤销时间',
  `revoke_user_id` bigint(20) NULL DEFAULT NULL COMMENT '撤销人用户ID（会长）',
  `revoke_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '撤销人姓名',
  `approval_version` int(11) NULL DEFAULT 1 COMMENT '纠错版本号（同一单据第几次纠错）',
  `freeze_status` tinyint(4) NULL DEFAULT 0 COMMENT '冻结状态（0未冻结 1已冻结 2已解冻）',
  `correction_status` tinyint(4) NULL DEFAULT 0 COMMENT '纠错状态（0待处理 1重审中 2已完成 3已撤销）',
  `council_decision` tinyint(4) NULL DEFAULT 0 COMMENT '是否理事会决议（0否 1是）',
  `council_decision_file` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '理事会决议文件',
  `new_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '重审流程实例ID',
  `correction_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '纠错处理结果',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发起人姓名',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_source_bill`(`source_bill_type` ASC, `source_bill_id` ASC) USING BTREE,
  INDEX `idx_freeze_status`(`freeze_status` ASC) USING BTREE,
  INDEX `idx_correction_status`(`correction_status` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_source_process_instance`(`source_process_instance_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '纠错申请单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_correction_bill
-- ----------------------------

-- ----------------------------
-- Table structure for oa_document_dispatch_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_document_dispatch_bill`;
CREATE TABLE `oa_document_dispatch_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '流程状态（0草稿 1审批中 2已通过 3已拒绝 4已取消）',
  `doc_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公文标题',
  `doc_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发文字号',
  `doc_number_prefix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发文字号前缀（如：无办发）',
  `doc_number_year` int(11) NULL DEFAULT NULL COMMENT '发文字号年份（如：2026）',
  `doc_number_serial` int(11) NULL DEFAULT NULL COMMENT '发文字号序号',
  `urgency_level` tinyint(4) NULL DEFAULT 0 COMMENT '紧急程度（0普通 1紧急 2特急）',
  `disclosure_category` tinyint(4) NULL DEFAULT 0 COMMENT '公开类别（0主动公开 1依申请公开 2不公开）',
  `issue_date` date NULL DEFAULT NULL COMMENT '发文日期',
  `main_recipients` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主送部门（逗号分隔）',
  `cc_departments` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '抄送部门（逗号分隔）',
  `signer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '签发人',
  `secrecy_level` tinyint(4) NULL DEFAULT 0 COMMENT '密级（0公开 1内部 2机密 3绝密）',
  `template_id` bigint(20) NULL DEFAULT NULL COMMENT '套红模板ID',
  `doc_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '公文正文',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '拟稿人姓名',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_secrecy_level`(`secrecy_level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '公文发文单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_document_dispatch_bill
-- ----------------------------

-- ----------------------------
-- Table structure for oa_expense_reimburse_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_expense_reimburse_bill`;
CREATE TABLE `oa_expense_reimburse_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '流程状态（0草稿 1审批中 2已通过 3已拒绝 4已取消）',
  `bill_type` tinyint(4) NOT NULL DEFAULT 2 COMMENT '鍗曟嵁绫诲瀷锛?-鏃ュ父鎶ラ攢 2-宸?梾鎶ラ攢',
  `travel_bill_code` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联出差申请单号',
  `cause` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鎶ラ攢浜嬬敱锛堟棩甯告姤閿?繀濉?級',
  `total_amount` decimal(15, 2) NOT NULL COMMENT '报销总金额（元）',
  `payment_status` tinyint(4) NULL DEFAULT 0 COMMENT '支付状态（0未支付 1已支付）',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '费用报销单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_expense_reimburse_bill
-- ----------------------------

-- ----------------------------
-- Table structure for oa_expense_reimburse_detail
