-- ----------------------------
-- Table structure for oa_file_info
-- ----------------------------
DROP TABLE IF EXISTS `oa_file_info`;
CREATE TABLE `oa_file_info`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '文件ID',
  `parent_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '父文件夹ID，0表示根目录',
  `file_type` tinyint(4) NOT NULL COMMENT '文件类型（0文件夹 1文件）',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名称',
  `file_size` bigint(20) NULL DEFAULT 0 COMMENT '文件大小（字节），文件夹为0',
  `file_extension` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件扩展名',
  `file_suffix` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件后缀名（不含点号）',
  `file_category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'other' COMMENT '文件分类（all全部 image图片 document文档 video视频 audio音频 archive压缩包 other其他）',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件存储路径',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件访问URL',
  `file_md5` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件MD5值',
  `is_shared` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否共享文件夹（0否 1是），仅文件夹有效',
  `share_type` tinyint(4) NULL DEFAULT NULL COMMENT '文件夹分享类型（0人员 1组织），仅共享文件夹有效',
  `share_permission` tinyint(4) NULL DEFAULT NULL COMMENT '分享权限（0仅查看 1可管理），仅共享文件夹有效',
  `owner_id` bigint(20) NOT NULL COMMENT '所有者ID（用户ID）',
  `owner_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所有者名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '所属部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属部门名称',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序序号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_owner_id`(`owner_id` ASC) USING BTREE,
  INDEX `idx_file_type`(`file_type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_file_category`(`file_category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA协同办公-企业云盘-文件信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_file_info
-- ----------------------------

-- ----------------------------
-- Table structure for oa_file_permission
-- ----------------------------
DROP TABLE IF EXISTS `oa_file_permission`;
CREATE TABLE `oa_file_permission`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `file_id` bigint(20) NOT NULL COMMENT '文件ID',
  `share_type` tinyint(4) NOT NULL COMMENT '分享类型（0人员 1组织）',
  `target_id` bigint(20) NOT NULL COMMENT '目标ID（人员ID或组织ID）',
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标名称（人员名称或组织名称）',
  `permission` tinyint(4) NOT NULL DEFAULT 0 COMMENT '权限（0仅查看 1可管理）',
  `inherit_permission` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否继承权限（0否 1是）',
  `share_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享路径（用于显示层级结构）',
  `root_share_id` bigint(20) NULL DEFAULT NULL COMMENT '根分享文件夹ID（用于快速定位）',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `share_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享码（可选）',
  `access_count` int(11) NOT NULL DEFAULT 0 COMMENT '访问次数',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_file_share_target`(`file_id` ASC, `share_type` ASC, `target_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_file_id`(`file_id` ASC) USING BTREE,
  INDEX `idx_target`(`share_type` ASC, `target_id` ASC) USING BTREE,
  INDEX `idx_root_share`(`root_share_id` ASC) USING BTREE,
  INDEX `idx_share_code`(`share_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA协同办公-企业云盘-文件权限表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_file_permission
-- ----------------------------

-- ----------------------------
-- Table structure for oa_incoming_document_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_incoming_document_bill`;
CREATE TABLE `oa_incoming_document_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '流程状态（0草稿 1审批中 2已通过 3已拒绝 4已取消）',
  `doc_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来文标题',
  `doc_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来文字号',
  `secrecy_level` tinyint(4) NULL DEFAULT 0 COMMENT '瀵嗙骇锛?鍏?紑 1鍐呴儴 2鏈哄瘑 3缁濆瘑锛',
  `receive_date` date NULL DEFAULT NULL COMMENT '收文日期',
  `doc_type` tinyint(4) NOT NULL COMMENT '来文类型（1上级文件 2平级文件 3下级文件 4群众来信 5其他）',
  `urgency_level` tinyint(4) NULL DEFAULT 0 COMMENT '紧急程度（0普通 1紧急 2特急）',
  `handling_dept_id` bigint(20) NULL DEFAULT NULL COMMENT '承办部门ID',
  `handling_dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '承办部门名称',
  `host_person` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '涓诲姙浜',
  `leader_instruction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '棰嗗?鎵圭ず',
  `handling_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '办理结果',
  `handling_deadline` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍔炵悊鏈熼檺',
  `content_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '鍐呭?鎽樿?',
  `handling_status` tinyint(4) NULL DEFAULT 0 COMMENT '办理状态（0待办理 1办理中 2已办结）',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登记人姓名',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_doc_type`(`doc_type` ASC) USING BTREE,
  INDEX `idx_handling_status`(`handling_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_secrecy_level`(`secrecy_level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收文办理单' ROW_FORMAT = DYNAMIC;

