-- ----------------------------
-- Table structure for oa_meeting_room
-- ----------------------------
DROP TABLE IF EXISTS `oa_meeting_room`;
CREATE TABLE `oa_meeting_room`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `room_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会议室名称',
  `room_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会议室位置',
  `room_type` int(11) NOT NULL COMMENT '会议室类型',
  `manager_id` bigint(20) NOT NULL COMMENT '负责人ID',
  `manager_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '负责人姓名',
  `manager_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '负责人联系方式',
  `available_status` int(11) NOT NULL DEFAULT 0 COMMENT '可用状态（0正常 1维修中 2不可用）',
  `pic_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议室图片URL',
  `seat_count` int(11) NULL DEFAULT NULL COMMENT '坐席数',
  `equipment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议室设备（逗号分隔：tv,computer,remote,projector,water_dispenser,locker）',
  `attachment_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件URL',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注（200字以内）',
  `allow_booking` bit(1) NOT NULL DEFAULT b'1' COMMENT '允许预定',
  `need_approval` bit(1) NOT NULL DEFAULT b'0' COMMENT '预定需审批',
  `booking_scope` int(11) NOT NULL DEFAULT 0 COMMENT '可用范围（0全部成员 1指定成员）',
  `booking_members` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '可预定成员ID（逗号分隔，当booking_scope=1时有效）',
  `sort` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_room_type`(`room_type` ASC) USING BTREE,
  INDEX `idx_available_status`(`available_status` ASC) USING BTREE,
  INDEX `idx_manager_id`(`manager_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会议室信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of oa_meeting_room
-- ----------------------------

-- ----------------------------
-- Table structure for oa_meeting_room_booking
-- ----------------------------
DROP TABLE IF EXISTS `oa_meeting_room_booking`;
CREATE TABLE `oa_meeting_room_booking`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例编号',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '单据状态（0草稿 1审批中 2审批通过 3审批拒绝 4已取消）',
  `room_id` bigint(20) NULL DEFAULT NULL COMMENT '会议室ID',
  `room_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议室名称',
  `room_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议室位置',
  `room_type` int(11) NULL DEFAULT NULL COMMENT '会议室类型',
  `meeting_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议名称',
  `meeting_start_time` datetime NULL DEFAULT NULL COMMENT '会议开始时间',
  `meeting_end_time` datetime NULL DEFAULT NULL COMMENT '会议结束时间',
  `moderator_id` bigint(20) NULL DEFAULT NULL COMMENT '主持人ID',
  `moderator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主持人姓名',
  `meeting_remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会议备注',
  `reminder_type` tinyint(4) NULL DEFAULT NULL COMMENT '会议提醒（1不提醒 2提前5分钟 3提前10分钟 4提前15分钟 5提前30分钟）',
  `attendees` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '与会人ID列表（JSON数组格式）',
  `attendee_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '与会人姓名列表（JSON数组格式）',
  `attachment_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '附件URL列表（JSON数组格式）',
  `use_status` tinyint(4) NULL DEFAULT 0 COMMENT '使用状态（0待使用 1使用中 2已完成 3已取消）',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NOT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_room_id`(`room_id` ASC) USING BTREE,
  INDEX `idx_company_id`(`company_id` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_use_status`(`use_status` ASC) USING BTREE,
  INDEX `idx_meeting_start_time`(`meeting_start_time` ASC) USING BTREE,
  INDEX `idx_meeting_end_time`(`meeting_end_time` ASC) USING BTREE,
  INDEX `idx_moderator_id`(`moderator_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会议室预定申请单' ROW_FORMAT = DYNAMIC;

