-- ----------------------------
-- Table structure for oa_project_initiation_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_project_initiation_bill`;
CREATE TABLE `oa_project_initiation_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '流程状态（0草稿 1审批中 2已通过 3已拒绝 4已取消）',
  `project_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目/活动名称',
  `project_type` tinyint(4) NOT NULL COMMENT '类型（1活动 2项目 3课题 4其他）',
  `priority` tinyint(4) NULL DEFAULT NULL COMMENT '优先级：1高 2中 3低',
  `project_category` tinyint(4) NULL DEFAULT NULL COMMENT '项目分类：1研发项目 2交付项目 3运维项目',
  `project_set_id` bigint(20) NULL DEFAULT NULL COMMENT '所属项目集ID',
  `project_set_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属项目集名称',
  `project_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目/活动方案',
  `budget_amount` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '预算金额（元）',
  `project_manager_id` bigint(20) NULL DEFAULT NULL COMMENT '项目经理ID',
  `project_manager_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目经理名称',
  `counterparty_type` tinyint(4) NULL DEFAULT NULL COMMENT '对方类型：1CRM客户 2ERP供应商',
  `counterparty_id` bigint(20) NULL DEFAULT NULL COMMENT '对方单位ID',
  `counterparty_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方单位名称',
  `counterparty_contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方联系人',
  `counterparty_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方联系电话',
  `start_date` date NULL DEFAULT NULL COMMENT '计划开始日期',
  `end_date` date NULL DEFAULT NULL COMMENT '计划结束日期',
  `related_contract_id` bigint(20) NULL DEFAULT NULL COMMENT '关联合同ID',
  `contract_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同编号',
  `contract_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同名称',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_project_type`(`project_type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_oa_pib_priority`(`priority` ASC) USING BTREE,
  INDEX `idx_oa_pib_project_category`(`project_category` ASC) USING BTREE,
  INDEX `idx_oa_pib_project_manager`(`project_manager_id` ASC) USING BTREE,
  INDEX `idx_oa_pib_counterparty_type`(`counterparty_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '活动/项目立项单' ROW_FORMAT = DYNAMIC;

