-- ----------------------------
-- Table structure for oa_seal
-- ----------------------------
DROP TABLE IF EXISTS `oa_seal`;
CREATE TABLE `oa_seal`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `seal_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章编号',
  `seal_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '印章名称',
  `seal_type` bigint(20) NOT NULL COMMENT '印章类型',
  `seal_cls` bigint(20) NOT NULL COMMENT '分类',
  `keeper_id` bigint(20) NULL DEFAULT NULL COMMENT '保管人ID',
  `keeper_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保管人名称',
  `keeper_dept_id` bigint(20) NULL DEFAULT NULL COMMENT '保管部门ID',
  `keeper_dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保管部门名称',
  `purchase_date` date NULL DEFAULT NULL COMMENT '购买日期',
  `enable_date` date NULL DEFAULT NULL COMMENT '启用日期',
  `disable_date` date NULL DEFAULT NULL COMMENT '停用日期',
  `sort` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态（0在库 1停用 2使用中）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_seal_no`(`seal_no` ASC) USING BTREE,
  INDEX `idx_seal_cls`(`seal_cls` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '印章信息表' ROW_FORMAT = DYNAMIC;

