-- ----------------------------
-- Table structure for oa_seal_apply_bill
-- ----------------------------
DROP TABLE IF EXISTS `oa_seal_apply_bill`;
CREATE TABLE `oa_seal_apply_bill`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程实例编号',
  `process_status` tinyint(4) NULL DEFAULT 0 COMMENT '单据状态（0草稿 1审批中 2审批通过 3审批拒绝 4已取消）',
  `seal_id` bigint(20) NOT NULL COMMENT '印章ID',
  `seal_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章编号',
  `seal_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '印章名称',
  `seal_type` tinyint(4) NULL DEFAULT NULL COMMENT '印章类型',
  `keeper_id` bigint(20) NULL DEFAULT NULL COMMENT '保管人ID',
  `keeper_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保管人名称',
  `keeper_dept_id` bigint(20) NULL DEFAULT NULL COMMENT '保管部门ID',
  `keeper_dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保管部门名称',
  `cause` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用章事由',
  `use_type` tinyint(4) NOT NULL COMMENT '用章类型（1合同用章 2证明用章 3公函用章 4其他用章）',
  `use_mode` tinyint(4) NOT NULL COMMENT '用章方式（1现场用章 2外借用章）',
  `document_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件标题',
  `document_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件类型',
  `document_count` int(11) NULL DEFAULT 1 COMMENT '文件份数',
  `contract_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '合同金额（合同用章时填写）',
  `contract_party` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同对方（合同用章时填写）',
  `expected_use_time` datetime NULL DEFAULT NULL COMMENT '预计用章时间',
  `actual_use_time` datetime NULL DEFAULT NULL COMMENT '实际用章时间',
  `expected_return_time` datetime NULL DEFAULT NULL COMMENT '预计归还时间（外借用章时填写）',
  `actual_return_time` datetime NULL DEFAULT NULL COMMENT '实际归还时间（外借用章时填写）',
  `use_status` tinyint(4) NULL DEFAULT 0 COMMENT '用章状态（0待处理 1已完成 2外借中 3已归还 4已逾期）',
  `is_urgent` tinyint(4) NULL DEFAULT 0 COMMENT '是否紧急（0否 1是）',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `dept_id` bigint(20) NOT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部门名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_seal_id`(`seal_id` ASC) USING BTREE,
  INDEX `idx_creator_id`(`creator` ASC) USING BTREE,
  INDEX `idx_process_status`(`process_status` ASC) USING BTREE,
  INDEX `idx_use_status`(`use_status` ASC) USING BTREE,
  INDEX `idx_use_mode`(`use_mode` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用章申请单' ROW_FORMAT = DYNAMIC;

