  INDEX `idx_creator`(`creator` ASC) USING BTREE,
  INDEX `idx_reimbursement_status`(`reimbursement_status` ASC) USING BTREE,
  INDEX `idx_linked_expense_bill_id`(`linked_expense_bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '差旅申请单' ROW_FORMAT = DYNAMIC;

