-- ----------------------------
-- Table structure for system_schedule
-- ----------------------------
DROP TABLE IF EXISTS `system_schedule`;
CREATE TABLE `system_schedule`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '日程ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '内容',
  `schedule_date` date NOT NULL COMMENT '日程日期',
  `start_time` time NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` time NULL DEFAULT NULL COMMENT '结束时间',
  `schedule_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '日程类型（字典：schedule_type）',
  `schedule_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '日程分类（字典：schedule_category）',
  `creator_id` bigint(20) NOT NULL COMMENT '创建人ID',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `is_pushed` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否推送（0否 1是）',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '状态（0开启 1停用）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_schedule_date`(`schedule_date` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_creator_id`(`creator_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '日程管理表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of system_schedule
-- ----------------------------

-- ----------------------------
-- Table structure for system_schedule_receiver
-- ----------------------------
DROP TABLE IF EXISTS `system_schedule_receiver`;
CREATE TABLE `system_schedule_receiver`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `schedule_id` bigint(20) NOT NULL COMMENT '日程ID',
  `receiver_id` bigint(20) NOT NULL COMMENT '接收人ID',
  `receiver_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '接收人姓名',
  `read_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '已读状态（0未读 1已读）',
  `read_time` datetime NULL DEFAULT NULL COMMENT '已读时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_schedule_receiver`(`schedule_id` ASC, `receiver_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_schedule_id`(`schedule_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_receiver_id`(`receiver_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_read_status`(`read_status` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '日程接收人关系表' ROW_FORMAT = DYNAMIC;

